import { calendarChannel } from "@/lib/booking";
import { redis } from "@/lib/redis";
import { getSession } from "@/lib/session";

export const dynamic = "force-dynamic";

// SSE stream of calendar changes for the admin UI.
// Each connection gets its own Redis subscriber (a subscribing connection
// can't run other commands), torn down when the client goes away.
export async function GET(request: Request) {
  const session = await getSession();
  if (!session) return new Response("unauthorized", { status: 401 });

  const channel = calendarChannel(session.businessId);
  const encoder = new TextEncoder();
  const sub = redis().duplicate();
  let closed = false;
  let ping: ReturnType<typeof setInterval> | undefined;

  const cleanup = () => {
    if (closed) return;
    closed = true;
    if (ping) clearInterval(ping);
    sub.removeAllListeners("message");
    sub.unsubscribe(channel).catch(() => {});
    sub.quit().catch(() => sub.disconnect());
    // quit can hang if Redis is unreachable; make sure the socket goes away.
    setTimeout(() => sub.disconnect(), 2_000).unref?.();
  };

  if (request.signal.aborted) {
    cleanup();
    return new Response(null, { status: 499 });
  }
  request.signal.addEventListener("abort", cleanup, { once: true });

  try {
    await sub.subscribe(channel);
  } catch (err) {
    cleanup();
    throw err;
  }
  if (closed) return new Response(null, { status: 499 });

  const stream = new ReadableStream({
    start(controller) {
      const send = (chunk: string) => {
        if (closed) return;
        try {
          controller.enqueue(encoder.encode(chunk));
        } catch {
          cleanup();
        }
      };
      send(`event: hello\ndata: {}\n\n`);
      sub.on("message", (_channel, message) => send(`data: ${message}\n\n`));
      ping = setInterval(() => send(`: ping\n\n`), 25_000);
    },
    cancel() {
      cleanup();
    },
  });

  return new Response(stream, {
    headers: {
      "Content-Type": "text/event-stream",
      "Cache-Control": "no-cache, no-transform",
      Connection: "keep-alive",
    },
  });
}
EOF
